// Token management
export const saveAuthToken = (token) => {
    localStorage.setItem('authToken', token);
  };
  
  export const getAuthToken = () => {
    return localStorage.getItem('authToken');
  };
  
  export const removeAuthToken = () => {
    localStorage.removeItem('authToken');
  };
  
  export const decodeToken = (token) => {
    try {
      return JSON.parse(atob(token));
    } catch (error) {
      console.error('Error decoding token:', error);
      return null;
    }
  };
  
  // User data management
  export const saveUserData = (userData) => {
    localStorage.setItem('userData', JSON.stringify(userData));
  };
  
  export const getUserData = () => {
    const userData = localStorage.getItem('userData');
    return userData ? JSON.parse(userData) : null;
  };
  
  export const removeUserData = () => {
    localStorage.removeItem('userData');
  };
  
  // Check if user is admin
  export const isUserAdmin = () => {
    const userData = getUserData();
    return userData && userData.role === 'admin';
  };
  
  // Route protection HOC (Higher Order Component)
  export const withAdminProtection = (Component) => {
    return (props) => {
      const userData = getUserData();
      const isAdmin = userData && userData.role === 'admin';
      
      if (!isAdmin) {
        return <AccessDenied />;
      }
      
      return <Component {...props} />;
    };
  };
  
  // Simple access denied component
  const AccessDenied = () => {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-gray-900 text-white p-4">
        <div className="text-red-500 text-6xl mb-6">⚠️</div>
        <h1 className="text-3xl font-bold mb-4 text-center">Access Denied</h1>
        <p className="text-lg text-gray-400 max-w-md text-center mb-8">
          You don't have permission to access this page or functionality.
          Administrator privileges are required.
        </p>
        <a 
          href="/"
          className="px-6 py-3 bg-green-700 text-white rounded-lg hover:bg-green-600 transition-colors"
        >
          Return to Home
        </a>
      </div>
    );
  };