import React, { useState, useEffect } from 'react';
import { X, Eye, EyeOff, Lock, User, LogIn, AlertTriangle, Shield } from 'lucide-react';
import { useAuth } from './AuthContext';

const LoginModal = ({ isOpen, onClose }) => {
  // States
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  
  // Auth context
  const { login } = useAuth();
  
  // Reset form when modal opens/closes
  useEffect(() => {
    if (isOpen) {
      setUsername('');
      setPassword('');
      setError('');
      setIsSubmitting(false);
    }
  }, [isOpen]);
  
  // Handle login submission
  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setIsSubmitting(true);
    
    try {
      const result = await login(username, password);
      
      if (result.success) {
        onClose();
      } else {
        setError(result.error || 'Invalid credentials');
      }
    } catch (error) {
      setError('An error occurred during login');
      console.error('Login error:', error);
    } finally {
      setIsSubmitting(false);
    }
  };
  
  // If modal is not open, don't render anything
  if (!isOpen) return null;
  
  return (
    <div className="fixed inset-0 bg-black bg-opacity-80 flex items-center justify-center z-50 p-4 transition-opacity duration-300">
      <div className="bg-gray-900 border border-dark-accent rounded-lg shadow-lg max-w-md w-full overflow-hidden animate-slideUp">
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-800">
          <div className="flex items-center space-x-2">
            <Shield size={20} className="text-dark-highlight" />
            <h2 className="text-xl font-semibold text-white">Admin Login</h2>
          </div>
          <button 
            onClick={onClose}
            className="text-gray-400 hover:text-white transition-colors"
            aria-label="Close modal"
          >
            <X size={20} />
          </button>
        </div>
        
        {/* Body */}
        <div className="p-6">
          {error && (
            <div className="flex items-start space-x-2 p-4 mb-6 bg-red-900/30 border border-red-800 rounded-lg">
              <AlertTriangle size={20} className="text-red-500 flex-shrink-0 mt-0.5" />
              <p className="text-red-200 text-sm">{error}</p>
            </div>
          )}
          
          <form onSubmit={handleSubmit}>
            {/* Username field */}
            <div className="mb-4">
              <label htmlFor="username" className="block text-dark-highlight mb-2 text-sm font-medium">Username</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none">
                  <User size={18} className="text-gray-500" />
                </div>
                <input
                  id="username"
                  type="text"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  className="bg-gray-800 border border-gray-700 text-white placeholder-gray-400 text-sm rounded-lg focus:ring-dark-highlight focus:border-dark-highlight block w-full pl-10 p-3"
                  placeholder="Enter admin username"
                  required
                  autoComplete="username"
                />
              </div>
            </div>
            
            {/* Password field */}
            <div className="mb-6">
              <label htmlFor="password" className="block text-dark-highlight mb-2 text-sm font-medium">Password</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none">
                  <Lock size={18} className="text-gray-500" />
                </div>
                <input
                  id="password"
                  type={showPassword ? "text" : "password"}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="bg-gray-800 border border-gray-700 text-white placeholder-gray-400 text-sm rounded-lg focus:ring-dark-highlight focus:border-dark-highlight block w-full pl-10 pr-10 p-3"
                  placeholder="Enter password"
                  required
                  autoComplete="current-password"
                />
                <button
                  type="button"
                  className="absolute inset-y-0 right-0 flex items-center pr-3 text-gray-400 hover:text-white"
                  onClick={() => setShowPassword(!showPassword)}
                  tabIndex="-1"
                  aria-label={showPassword ? "Hide password" : "Show password"}
                >
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
              <p className="mt-2 text-xs text-gray-400">Default first-time password: "loremipsum"</p>
            </div>
            
            {/* Submit button */}
            <button
              type="submit"
              disabled={isSubmitting}
              className={`w-full flex items-center justify-center space-x-2 ${
                isSubmitting ? 'bg-gray-700 cursor-not-allowed' : 'bg-dark-accent hover:bg-dark-highlight'
              } text-white font-medium rounded-lg text-sm px-5 py-3 transition-colors`}
            >
              <LogIn size={18} />
              <span>{isSubmitting ? 'Logging in...' : 'Login'}</span>
            </button>
          </form>
        </div>
        
        {/* Footer */}
        <div className="px-6 py-4 bg-gray-800/50 border-t border-gray-800">
          <p className="text-gray-400 text-xs text-center">
            This login is only for site administrators. Guests do not need to log in to browse content.
          </p>
        </div>
      </div>
    </div>
  );
};

export default LoginModal;