import React, { useState } from 'react';
import { useAuth } from './AuthContext';
import { 
  Shield, 
  Settings, 
  LogOut, 
  User, 
  BookOpen, 
  Code, 
  Briefcase,
  Key,
  ChevronDown,
  ChevronUp
} from 'lucide-react';

const AdminDashboard = () => {
  const { isAuthenticated, isAdmin, user, logout } = useAuth();
  const [isExpanded, setIsExpanded] = useState(false);
  const [showPasswordModal, setShowPasswordModal] = useState(false);

  // If not authenticated or not admin, show nothing
  if (!isAuthenticated || !isAdmin) {
    return null;
  }

  return (
    <div className="fixed bottom-4 left-4 z-40">
      {/* Collapsible admin panel */}
      <div className={`
        bg-gray-900 border border-dark-accent rounded-lg shadow-lg overflow-hidden
        transition-all duration-300 ease-in-out
        ${isExpanded ? 'w-64' : 'w-14'}
      `}>
        {/* Header with collapse toggle */}
        <div 
          className="flex items-center p-3 border-b border-gray-800 cursor-pointer hover:bg-gray-800/50"
          onClick={() => setIsExpanded(!isExpanded)}
        >
          <Shield size={20} className="text-dark-highlight flex-shrink-0" />
          {isExpanded && (
            <>
              <span className="ml-3 text-white font-medium">Admin Panel</span>
              <div className="ml-auto">
                {isExpanded ? <ChevronDown size={16} className="text-gray-400" /> : <ChevronUp size={16} className="text-gray-400" />}
              </div>
            </>
          )}
        </div>

        {/* User info */}
        {isExpanded && (
          <div className="p-3 border-b border-gray-800 bg-gray-800/20">
            <div className="flex items-center">
              <div className="bg-dark-highlight/20 p-2 rounded-full">
                <User size={16} className="text-dark-highlight" />
              </div>
              <div className="ml-3">
                <div className="text-sm font-medium text-white">{user.username}</div>
                <div className="text-xs text-gray-400">Administrator</div>
              </div>
            </div>
          </div>
        )}

        {/* Menu items */}
        <div className="p-2">
          {/* WikiDEDIA admin */}
          <a 
            href="/wikidedia"
            className={`flex items-center p-2 rounded-md hover:bg-gray-800/70 transition-colors ${
              isExpanded ? '' : 'justify-center'
            }`}
          >
            <BookOpen size={18} className="text-green-400" />
            {isExpanded && <span className="ml-3 text-sm text-white">Manage Wiki</span>}
          </a>

          {/* MasteryHub admin */}
          <a 
            href="/masteryhub"
            className={`flex items-center p-2 rounded-md hover:bg-gray-800/70 transition-colors ${
              isExpanded ? '' : 'justify-center'
            }`}
          >
            <Code size={18} className="text-blue-400" />
            {isExpanded && <span className="ml-3 text-sm text-white">Manage Skills</span>}
          </a>

          {/* ServiceHub admin */}
          <a 
            href="/servicehub"
            className={`flex items-center p-2 rounded-md hover:bg-gray-800/70 transition-colors ${
              isExpanded ? '' : 'justify-center'
            }`}
          >
            <Briefcase size={18} className="text-purple-400" />
            {isExpanded && <span className="ml-3 text-sm text-white">Manage Services</span>}
          </a>

          {/* Change password */}
          <button 
            onClick={() => setShowPasswordModal(true)}
            className={`flex items-center p-2 rounded-md hover:bg-gray-800/70 transition-colors w-full ${
              isExpanded ? '' : 'justify-center'
            }`}
          >
            <Key size={18} className="text-yellow-400" />
            {isExpanded && <span className="ml-3 text-sm text-white">Change Password</span>}
          </button>

          {/* Logout */}
          <button 
            onClick={logout}
            className={`flex items-center p-2 rounded-md hover:bg-gray-800/70 transition-colors w-full ${
              isExpanded ? '' : 'justify-center'
            }`}
          >
            <LogOut size={18} className="text-red-400" />
            {isExpanded && <span className="ml-3 text-sm text-white">Logout</span>}
          </button>
        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;