import React, { useState, useEffect } from 'react';
import { X, Eye, EyeOff, Lock, Check, AlertTriangle, Info, Shield } from 'lucide-react';
import { useAuth } from './AuthContext';

import PropTypes from 'prop-types';

const PasswordChangeModal = ({ isOpen, onClose }) => {
  // States
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [error, setError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [validationMessages, setValidationMessages] = useState([]);
  
  // Auth context
  const { changePassword, validatePassword, needsPasswordChange } = useAuth();
  
  // Reset form when modal opens/closes
  useEffect(() => {
    if (isOpen) {
      setNewPassword('');
      setConfirmPassword('');
      setError('');
      setIsSubmitting(false);
      setValidationMessages([]);
    }
  }, [isOpen]);
  
  // Validate password as user types
  useEffect(() => {
    if (newPassword) {
      const messages = [];
      
      // Length check
      if (newPassword.length < 24) {
        messages.push({
          id: 'length',
          text: 'Password must be at least 24 characters long',
          valid: false
        });
      } else {
        messages.push({
          id: 'length',
          text: 'Password length is sufficient (24+ characters)',
          valid: true
        });
      }
      
      // Letters check
      if (!/[a-zA-Z]/.test(newPassword)) {
        messages.push({
          id: 'letters',
          text: 'Password must contain letters',
          valid: false
        });
      } else {
        messages.push({
          id: 'letters',
          text: 'Password contains letters',
          valid: true
        });
      }
      
      // Numbers check
      if (!/[0-9]/.test(newPassword)) {
        messages.push({
          id: 'numbers',
          text: 'Password must contain numbers',
          valid: false
        });
      } else {
        messages.push({
          id: 'numbers',
          text: 'Password contains numbers',
          valid: true
        });
      }
      
      // Special characters check
      if (!/[^a-zA-Z0-9]/.test(newPassword)) {
        messages.push({
          id: 'special',
          text: 'Password must contain special characters',
          valid: false
        });
      } else {
        messages.push({
          id: 'special',
          text: 'Password contains special characters',
          valid: true
        });
      }
      
      // Match check (only if confirm password is not empty)
      if (confirmPassword) {
        if (newPassword !== confirmPassword) {
          messages.push({
            id: 'match',
            text: 'Passwords do not match',
            valid: false
          });
        } else {
          messages.push({
            id: 'match',
            text: 'Passwords match',
            valid: true
          });
        }
      }
      
      setValidationMessages(messages);
    } else {
      setValidationMessages([]);
    }
  }, [newPassword, confirmPassword]);
  
  // Check if all validations pass
  const allValidationsPass = () => {
    if (validationMessages.length === 0) return false;
    return validationMessages.every(msg => msg.valid);
  };
  
  // Handle password change submission
  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    
    // Final validation check
    if (newPassword !== confirmPassword) {
      setError('Passwords do not match');
      return;
    }
    
    const validation = validatePassword(newPassword);
    if (!validation.valid) {
      setError(validation.message);
      return;
    }
    
    setIsSubmitting(true);
    
    try {
      const result = await changePassword(newPassword);
      
      if (result.success) {
        onClose();
      } else {
        setError(result.error || 'Failed to change password');
      }
    } catch (error) {
      setError('An error occurred while changing password');
      console.error('Password change error:', error);
    } finally {
      setIsSubmitting(false);
    }
  };
  
  // If modal is not open, don't render anything
  if (!isOpen) return null;
  
  return (
    <div className="fixed inset-0 bg-black bg-opacity-90 flex items-center justify-center z-50 p-4 transition-opacity duration-300">
      <div className="bg-gray-900 border border-dark-accent rounded-lg shadow-lg max-w-lg w-full overflow-hidden animate-slideUp">
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-800">
          <div className="flex items-center space-x-2">
            <Shield size={20} className="text-dark-highlight" />
            <h2 className="text-xl font-semibold text-white">
              {needsPasswordChange ? 'Required Password Change' : 'Change Admin Password'}
            </h2>
          </div>
          {!needsPasswordChange && (
            <button 
              onClick={onClose}
              className="text-gray-400 hover:text-white transition-colors"
              aria-label="Close modal"
            >
              <X size={20} />
            </button>
          )}
        </div>
        
        {/* Body */}
        <div className="p-6">
          {needsPasswordChange && (
            <div className="flex items-start space-x-2 p-4 mb-6 bg-yellow-900/30 border border-yellow-800 rounded-lg">
              <AlertTriangle size={20} className="text-yellow-500 flex-shrink-0 mt-0.5" />
              <div>
                <h3 className="text-yellow-300 font-medium">Password Change Required</h3>
                <p className="text-yellow-200 text-sm mt-1">
                  You're using the default password. For security reasons, you must set a new password before continuing.
                </p>
              </div>
            </div>
          )}
          
          {error && (
            <div className="flex items-start space-x-2 p-4 mb-6 bg-red-900/30 border border-red-800 rounded-lg">
              <AlertTriangle size={20} className="text-red-500 flex-shrink-0 mt-0.5" />
              <p className="text-red-200 text-sm">{error}</p>
            </div>
          )}
          
          <form onSubmit={handleSubmit}>
            {/* New password field */}
            <div className="mb-4">
              <label htmlFor="newPassword" className="block text-dark-highlight mb-2 text-sm font-medium">New Password</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none">
                  <Lock size={18} className="text-gray-500" />
                </div>
                <input
                  id="newPassword"
                  type={showPassword ? "text" : "password"}
                  value={newPassword}
                  onChange={(e) => setNewPassword(e.target.value)}
                  className="bg-gray-800 border border-gray-700 text-white placeholder-gray-400 text-sm rounded-lg focus:ring-dark-highlight focus:border-dark-highlight block w-full pl-10 pr-10 p-3"
                  placeholder="Enter new password (24+ characters)"
                  required
                  autoComplete="new-password"
                />
                <button
                  type="button"
                  className="absolute inset-y-0 right-0 flex items-center pr-3 text-gray-400 hover:text-white"
                  onClick={() => setShowPassword(!showPassword)}
                  tabIndex="-1"
                  aria-label={showPassword ? "Hide password" : "Show password"}
                >
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
            </div>
            
            {/* Confirm password field */}
            <div className="mb-6">
              <label htmlFor="confirmPassword" className="block text-dark-highlight mb-2 text-sm font-medium">Confirm Password</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none">
                  <Lock size={18} className="text-gray-500" />
                </div>
                <input
                  id="confirmPassword"
                  type={showConfirmPassword ? "text" : "password"}
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  className="bg-gray-800 border border-gray-700 text-white placeholder-gray-400 text-sm rounded-lg focus:ring-dark-highlight focus:border-dark-highlight block w-full pl-10 pr-10 p-3"
                  placeholder="Confirm new password"
                  required
                  autoComplete="new-password"
                />
                <button
                  type="button"
                  className="absolute inset-y-0 right-0 flex items-center pr-3 text-gray-400 hover:text-white"
                  onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                  tabIndex="-1"
                  aria-label={showConfirmPassword ? "Hide confirm password" : "Show confirm password"}
                >
                  {showConfirmPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
            </div>
            
            {/* Password requirements */}
            <div className="mb-6">
              <h3 className="flex items-center text-sm font-medium text-dark-highlight mb-3">
                <Info size={16} className="mr-2" />
                Password Requirements
              </h3>
              <ul className="space-y-2 text-sm">
                {validationMessages.map(message => (
                  <li 
                    key={message.id}
                    className={`flex items-start space-x-2 ${
                      message.valid ? 'text-green-400' : 'text-gray-400'
                    }`}
                  >
                    {message.valid ? (
                      <Check size={16} className="flex-shrink-0 mt-0.5" />
                    ) : (
                      <div className="w-4 h-4 flex-shrink-0 mt-0.5 border border-gray-600 rounded-full" />
                    )}
                    <span>{message.text}</span>
                  </li>
                ))}
              </ul>
            </div>
            
            {/* Submit button */}
            <button
              type="submit"
              disabled={isSubmitting || !allValidationsPass()}
              className={`w-full flex items-center justify-center space-x-2 ${
                isSubmitting || !allValidationsPass() 
                  ? 'bg-gray-700 cursor-not-allowed' 
                  : 'bg-dark-accent hover:bg-dark-highlight'
              } text-white font-medium rounded-lg text-sm px-5 py-3 transition-colors`}
            >
              <Check size={18} />
              <span>{isSubmitting ? 'Saving...' : 'Change Password'}</span>
            </button>
          </form>
        </div>
        
        {/* Footer */}
        <div className="px-6 py-4 bg-gray-800/50 border-t border-gray-800">
          <p className="text-gray-400 text-xs text-center">
            Your password should be at least 24 characters long and include letters, numbers and special characters. 
            Consider using a passphrase that is both secure and memorable.
          </p>
        </div>
      </div>
    </div>
    );
  
  };
  
  export default PasswordChangeModal;