import React, { createContext, useState, useContext, useEffect } from 'react';
import { 
  saveAuthToken, 
  getAuthToken, 
  removeAuthToken, 
  decodeToken,
  saveUserData,
  getUserData,
  removeUserData
} from './authUtils';

// Create the context
const AuthContext = createContext();

// Hook for easy context consumption
export const useAuth = () => useContext(AuthContext);

export const AuthProvider = ({ children }) => {
  // States for user authentication
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [user, setUser] = useState(null);
  const [isAdmin, setIsAdmin] = useState(false);
  const [loading, setLoading] = useState(true);
  const [needsPasswordChange, setNeedsPasswordChange] = useState(false);

  // Check authentication status on mount
  useEffect(() => {
    const initializeAuth = async () => {
      try {
        const token = getAuthToken();
        const userData = getUserData();
        
        if (token && userData) {
          const decodedToken = decodeToken(token);
          
          // Check if token is expired
          if (decodedToken && decodedToken.exp * 1000 > Date.now()) {
            setUser(userData);
            setIsAuthenticated(true);
            setIsAdmin(userData.role === 'admin');
            setNeedsPasswordChange(userData.needsPasswordChange || false);
          } else {
            // Token expired, clear auth
            handleLogout();
          }
        }
      } catch (error) {
        console.error('Auth initialization error:', error);
        handleLogout();
      } finally {
        setLoading(false);
      }
    };

    initializeAuth();
  }, []);

  // Login function
  const handleLogin = async (username, password) => {
    try {
      // In a real app, this would be an API call
      // For demo purposes, we'll validate locally
      if (username === 'admin' && password === 'loremipsum') {
        // First login detected - default password used
        const userData = {
          id: 1,
          username: 'admin',
          role: 'admin',
          needsPasswordChange: true
        };
        
        // Create token (this would normally come from the server)
        const token = btoa(JSON.stringify({
          id: userData.id,
          username: userData.username,
          role: userData.role,
          exp: Math.floor(Date.now() / 1000) + 24 * 60 * 60 // 24 hours
        }));
        
        // Save auth data
        saveAuthToken(token);
        saveUserData(userData);
        
        // Update state
        setUser(userData);
        setIsAuthenticated(true);
        setIsAdmin(true);
        setNeedsPasswordChange(true);
        
        return { success: true, needsPasswordChange: true };
      } else if (username === 'admin') {
        // Admin login attempt with stored password 
        const storedUserData = localStorage.getItem('adminPasswordHash');
        
        if (storedUserData) {
          const { passwordHash, salt } = JSON.parse(storedUserData);
          
          // Hash the input password with the stored salt
          const hashedPassword = await hashPassword(password, salt);
          
          if (hashedPassword === passwordHash) {
            const userData = {
              id: 1,
              username: 'admin',
              role: 'admin',
              needsPasswordChange: false
            };
            
            // Create token
            const token = btoa(JSON.stringify({
              id: userData.id,
              username: userData.username,
              role: userData.role,
              exp: Math.floor(Date.now() / 1000) + 24 * 60 * 60 // 24 hours
            }));
            
            // Save auth data
            saveAuthToken(token);
            saveUserData(userData);
            
            // Update state
            setUser(userData);
            setIsAuthenticated(true);
            setIsAdmin(true);
            setNeedsPasswordChange(false);
            
            return { success: true, needsPasswordChange: false };
          }
        }
      }
      
      // Failed login
      return { 
        success: false, 
        error: 'Invalid username or password'
      };
    } catch (error) {
      console.error('Login error:', error);
      return { 
        success: false, 
        error: 'An error occurred during login'
      };
    }
  };

  // Logout function
  const handleLogout = () => {
    removeAuthToken();
    removeUserData();
    setUser(null);
    setIsAuthenticated(false);
    setIsAdmin(false);
    setNeedsPasswordChange(false);
  };

  // Change password function
  const handlePasswordChange = async (newPassword) => {
    try {
      if (!isAuthenticated || !isAdmin) {
        throw new Error('Unauthorized');
      }
      
      // Generate a random salt
      const salt = generateSalt();
      
      // Hash the password with the salt
      const passwordHash = await hashPassword(newPassword, salt);
      
      // Store the hashed password and salt (in a real app, this would be server-side)
      localStorage.setItem('adminPasswordHash', JSON.stringify({ passwordHash, salt }));
      
      // Update user data
      const updatedUserData = {
        ...user,
        needsPasswordChange: false
      };
      
      saveUserData(updatedUserData);
      
      // Update state
      setUser(updatedUserData);
      setNeedsPasswordChange(false);
      
      return { success: true };
    } catch (error) {
      console.error('Password change error:', error);
      return { 
        success: false, 
        error: 'An error occurred during password change'
      };
    }
  };

  // Utility function to generate salt
  const generateSalt = () => {
    const array = new Uint8Array(16);
    window.crypto.getRandomValues(array);
    return Array.from(array, byte => byte.toString(16).padStart(2, '0')).join('');
  };

  // Utility function to hash password with salt
  const hashPassword = async (password, salt) => {
    // Convert password and salt to Uint8Array
    const encoder = new TextEncoder();
    const passwordData = encoder.encode(password + salt);
    
    // Hash using SubtleCrypto
    const hashBuffer = await window.crypto.subtle.digest('SHA-256', passwordData);
    
    // Convert to hex string
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
  };

  // Validate password strength
  const validatePassword = (password) => {
    // Must be at least 24 characters
    if (password.length < 24) {
      return { 
        valid: false, 
        message: 'Password must be at least 24 characters long'
      };
    }
    
    // Must contain letters
    if (!/[a-zA-Z]/.test(password)) {
      return { 
        valid: false, 
        message: 'Password must contain letters'
      };
    }
    
    // Must contain numbers
    if (!/[0-9]/.test(password)) {
      return { 
        valid: false, 
        message: 'Password must contain numbers'
      };
    }
    
    // Must contain special characters
    if (!/[^a-zA-Z0-9]/.test(password)) {
      return { 
        valid: false, 
        message: 'Password must contain special characters'
      };
    }
    
    return { valid: true };
  };

  // Provides context values to children components
  const contextValue = {
    isAuthenticated,
    isAdmin,
    user,
    loading,
    needsPasswordChange,
    login: handleLogin,
    logout: handleLogout,
    changePassword: handlePasswordChange,
    validatePassword
  };

  return (
    <AuthContext.Provider value={contextValue}>
      {children}
    </AuthContext.Provider>
  );
};

export default AuthContext;