import React, { useState, useEffect, lazy, Suspense } from 'react';
import App from './App';
import { AuthProvider, useAuth } from './components/AuthContext';
import LoginModal from './components/LoginModal';
import PasswordChangeModal from './components/PasswordChangeModal';

// Lazy load pages for better performance
const MasteryHubPage = lazy(() => import('./pages/MasteryHubPage'));
const ServiceHubPage = lazy(() => import('./pages/ServiceHubPage'));
const WikiDEDIAPage = lazy(() => import('./pages/WikiDEDIAPage'));

// Loading component for suspense fallback
const LoadingPage = () => (
  <div className="flex items-center justify-center min-h-screen bg-gray-900 text-dark-highlight">
    <div className="text-center">
      <div className="animate-spin rounded-full h-16 w-16 border-t-2 border-b-2 border-dark-highlight mx-auto mb-4"></div>
      <h2 className="text-xl">Loading...</h2>
    </div>
  </div>
);

// Main Router component
const Router = () => {
  return (
    <AuthProvider>
      <RouterContent />
    </AuthProvider>
  );
};

// Router content using auth context
const RouterContent = () => {
  const [currentPath, setCurrentPath] = useState(window.location.pathname);
  const [showLoginModal, setShowLoginModal] = useState(false);
  const { isAuthenticated, isAdmin, needsPasswordChange } = useAuth();
  
  useEffect(() => {
    // Handle browser history changes
    const handleLocationChange = () => {
      setCurrentPath(window.location.pathname);
    };
    
    // Intercept link clicks to handle SPA navigation
    const handleLinkClick = (event) => {
      // Find the closest <a> tag (if it exists)
      let anchor = event.target;
      while (anchor && anchor.tagName !== 'A') {
        anchor = anchor.parentElement;
      }
      
      // If it's an internal link, handle the navigation
      if (
        anchor && 
        anchor.href && 
        anchor.href.startsWith(window.location.origin) &&
        !anchor.hasAttribute('target') &&
        !anchor.hasAttribute('download') &&
        anchor.getAttribute('rel') !== 'external'
      ) {
        event.preventDefault();
        
        const path = anchor.href.replace(window.location.origin, '');
        
        // Use history API to change URL without reloading the page
        window.history.pushState(null, '', path);
        setCurrentPath(path);
        
        // Scroll to the top of the page
        window.scrollTo(0, 0);
      }
    };
    
    // Listen for clicks on the entire page
    document.addEventListener('click', handleLinkClick);
    
    // Listen for history changes (back/forward browser buttons)
    window.addEventListener('popstate', handleLocationChange);
    
    return () => {
      document.removeEventListener('click', handleLinkClick);
      window.removeEventListener('popstate', handleLocationChange);
    };
  }, []);

  // Function to check if a route requires admin access
  const isAdminRoute = (path) => {
    // Define paths that need admin privileges for editing
    // For now, all content is viewable by guests, but editing requires admin
    return false; // We handle admin access within components now
  };
  
  // Map paths to their corresponding components
  const renderRoute = () => {
    // Before rendering admin routes, check if user is logged in
    if (isAdminRoute(currentPath) && !isAuthenticated) {
      setShowLoginModal(true);
      return <App />;
    }

    // Handle WikiDEDIA routes
    if (currentPath.startsWith('/wikidedia')) {
      return (
        <Suspense fallback={<LoadingPage />}>
          <WikiDEDIAPage path={currentPath} />
        </Suspense>
      );
    }
    
    switch (currentPath) {
      case '/masteryhub':
        return (
          <Suspense fallback={<LoadingPage />}>
            <MasteryHubPage />
          </Suspense>
        );
      
      case '/madebyme':
        // Future MadeByMe page
        return <App initialSection="madebyme" />;
        
      case '/servicehub':
        return (
          <Suspense fallback={<LoadingPage />}>
            <ServiceHubPage />
          </Suspense>
        );
        
      default:
        // Homepage or unrecognized paths return to home
        return <App />;
    }
  };
  
  return (
    <>
      {renderRoute()}
      
      {/* Login Modal */}
      <LoginModal isOpen={showLoginModal} onClose={() => setShowLoginModal(false)} />
      
      {/* Password Change Modal - shown when needed */}
      <PasswordChangeModal 
        isOpen={needsPasswordChange} 
        onClose={() => {/* Can't close if change is required */}} 
      />
    </>
  );
};

export default Router;